from abc import ABC, abstractmethod

# Interface (in Python, use ABC with only abstract methods)
class Drawable(ABC):
    @abstractmethod
    def draw(self):
        pass

class Saveable(ABC):
    @abstractmethod
    def save(self, filename):
        pass

# A class can implement multiple interfaces
class Document(Drawable, Saveable):
    def __init__(self, content):
        self.content = content

    def draw(self):
        print(f"Rendering: {self.content}")

    def save(self, filename):
        print(f"Saving to {filename}")

# Function works with any Drawable
def render_all(drawables):
    for item in drawables:
        item.draw()

